+      float weights[kPartials], denominator = 0.f;
+#pragma unroll
+      for (int p = 0; p < kPartials; ++p) {
+        const int row = partial_row(waveBase, p);
+        weights[p] = weight_of(ldsMax[row], maxAll);
+        denominator = fmaf(weights[p], ldsSum[row], denominator);
+      }
