+          partialSum[partialRow] = denominator;
+        }
+      }
+      for (int d = thread; d < kHeadDim; d += kThreads) {
+        float numerator = 0.f;
+#pragma unroll
+        for (int p = 0; p < kPartials; ++p)
+          numerator = fmaf(
+              weights[p],
+              ldsAccum[partial_row(waveBase, p) * kPartialStride +
