+          partialAcc[partialRow * kHeadDim + d] = numerator;
+      }
+    }
+
+    if constexpr (kMaxSegments > 1) {
+      // The last segment to arrive merges and resets the counter.
+      __threadfence();
+      if (thread == 0)
