+          (size_t)((block * kBlockKeys + keyTile * 16) % kPageSize) *
+              kKvRowElems +
+          (size_t)laneHalf * kKvRowElems + laneDim;
+#pragma unroll
+      for (int e = 0; e < 8; ++e)
+        tile.v[e] =
