+#pragma unroll
+      for (int rt = 0; rt < kRowTiles; ++rt) scores[rt] = f8{};
+#pragma unroll
+      for (int c = 0; c < kPartChunks; ++c) {
+        const e16 kOperand =
+            *(const e16*)(kTile + laneRow * kTileRowBytes + c * 32);
+#pragma unroll
+        for (int rt = 0; rt < kRowTiles; ++rt) {
+          const e16 qOperand =
+              *(const e16*)&qShared[rt * 16 + laneRow][(firstChunk + c) * 16];
+          if (!(kAblate & 16) || c == 0)
