+      }
+      if constexpr (kHeadDimSplit > 1 && !(kAblate & 128)) {
+        // Sum the parts in the same order in every wave so all agree exactly.
+        asm volatile("" ::: "memory");
+#pragma unroll
+        for (int rt = 0; rt < kRowTiles; ++rt)
