+      bool allLive = true;
+#pragma unroll
+      for (int ls = 0; ls < kWaveSubTiles; ++ls) allLive = allLive && live[ls];
+      if constexpr (kWaveSubTiles == 1) {
+        if (live[0]) qk.template operator()<false>();
+      } else if (__builtin_amdgcn_readfirstlane((int)allLive)) {
