+#pragma unroll
+        for (int c = 0; c < kPartChunks; ++c)
+#pragma unroll
+          for (int ls = 0, st = keyWave; ls < kWaveSubTiles;
+               ++ls, st += kKeyWaves) {
+            scores[ls] = wmma(*(const e16*)&kTile[buffer][st * 16 + laneRow]
+                                                 [(firstChunk + c) * 16],
