+      const float newMax = tileMax > runMax + kMaxSlack ? tileMax : runMax;
+      const float safeMax = newMax == -INFINITY ? 0.f : newMax;
+      const float rescale = __builtin_amdgcn_exp2f(runMax - safeMax);
+      runMax = newMax;
