+        for (int j = 0; j < kLaneDims; ++j) accum[j] *= rescale;
+      e16 pOperand[kWaveSubTiles];
+      float tileSum = 0.f;
+#pragma unroll
+      for (int ls = 0; ls < kWaveSubTiles; ++ls) {
+        float probs[8];
+#pragma unroll
+        for (int e = 0; e < 8; ++e) {
+          probs[e] = __builtin_amdgcn_exp2f(
