+          }
+          lds_barrier();
+          buffer ^= 1;
+        }
+      } else if constexpr (kSplitStage) {
+        issue(keyBegin);
+        stage(0, keyBegin);
+        if (keyBegin + kKeyTile < stepsEnd) issue(keyBegin + kKeyTile);
+        lds_barrier();
+        for (int keyStart = keyBegin; keyStart < stepsEnd;
+             keyStart += kKeyTile) {
