+      for (int j = 0; j < kLaneDims; ++j) accum[j] *= weight;
+      runMax = maxAll;
+      runSum = total;
+#pragma unroll
+      for (int j = 0; j < kLaneDims; ++j) {
+        if (keyWave > 0) keySlot[wave][lane] = accum[j];
