+    // Split KV: publish (O, max, sum); the last segment to arrive merges and
+    // resets the counter.
+    const size_t partialBase = (groupSlot + segment) * kBlockRows;
+    if (owner) {
+      const size_t partialRow = partialBase + rowWave * 16 + laneRow;
