+    }
+    __threadfence();
+    __shared__ int isLast;
+    __syncthreads();
+    if (thread == 0) {
+      isLast = atomicAdd(&counters[counter], 1) == numSegments - 1;
+      if (isLast) counters[counter] = 0;
+    }
+    __syncthreads();
+    if (!isLast) return;
+    __threadfence();
